package ir.masoud.yadgoo;
import android.app.*;import android.content.*;
public class ReminderReceiver extends android.content.BroadcastReceiver {
 public void onReceive(Context c, Intent i){String channel="reminders";NotificationManager m=c.getSystemService(NotificationManager.class);NotificationChannel ch=new NotificationChannel(channel,"یادآوری‌های یادگو",NotificationManager.IMPORTANCE_HIGH);ch.enableVibration(true);ch.setVibrationPattern(new long[]{0,350,180,350});m.createNotificationChannel(ch);Intent open=c.getPackageManager().getLaunchIntentForPackage(c.getPackageName());PendingIntent content=open==null?null:PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=new Notification.Builder(c,channel).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("یادگو: وقت انجام کار").setContentText(i.getStringExtra("title")).setStyle(new Notification.BigTextStyle().bigText(i.getStringExtra("title"))).setCategory(Notification.CATEGORY_REMINDER).setPriority(Notification.PRIORITY_HIGH).setDefaults(Notification.DEFAULT_ALL).setAutoCancel(true);if(content!=null)b.setContentIntent(content);m.notify(i.getIntExtra("id",0),b.build());}
}
